// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;

    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(address caller, address recipient, uint256 initBalance) public {
        initBalance = bound(initBalance, 0, 1 ether);
        vm.assume(caller != address(this));

        vm.deal(address(c), initBalance);

        bool ok;
        vm.prank(caller);
        try c.withdrawAll(recipient) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(address(c).balance == initBalance);
    }
}
